<?php
namespace Tests\Feature;
use App\Models\{Category,Product,Purchase,Sale,Supplier,User};
use Illuminate\Foundation\Testing\RefreshDatabase;
use Tests\TestCase;
class InventoryWorkflowTest extends TestCase {
 use RefreshDatabase;
 private function user(string $role='staff'): User {return User::create(['name'=>ucfirst($role),'username'=>$role.'-'.uniqid(),'email'=>uniqid().'@example.test','password'=>'Password123!','role'=>$role]);}
 private function product(int $stock=10): array {$c=Category::create(['name'=>'Category '.uniqid()]);$s=Supplier::create(['name'=>'Supplier '.uniqid()]);$p=Product::create(['sku'=>'SKU-'.uniqid(),'name'=>'Test item','category_id'=>$c->id,'supplier_id'=>$s->id,'price'=>'12.50','purchase_price'=>'8.25','selling_price'=>'12.50','stock'=>$stock,'minimum_stock'=>2]);return [$p,$s];}
 public function test_guest_is_redirected_from_dashboard_and_login_password_is_checked(): void {$this->get('/dashboard')->assertRedirect('/login');$u=$this->user();$this->post('/login',['username'=>$u->username,'password'=>'wrong'])->assertSessionHasErrors('username');$this->post('/login',['username'=>$u->username,'password'=>'Password123!'])->assertRedirect('/dashboard');$this->post('/logout')->assertRedirect('/login');}
 public function test_staff_cannot_open_admin_only_product_or_user_management(): void {$staff=$this->user();$this->actingAs($staff)->get('/products/create')->assertForbidden();$this->actingAs($staff)->get('/users')->assertForbidden();}
 public function test_purchase_increases_stock_and_records_header_and_items(): void {[$p,$supplier]=$this->product(3);$user=$this->user();$this->actingAs($user)->post('/purchases',['supplier_id'=>$supplier->id,'items'=>[['product_id'=>$p->id,'quantity'=>4,'unit_cost'=>'8.25'],['product_id'=>'','quantity'=>'','unit_cost'=>'']]])->assertRedirect();$this->assertSame(7,$p->fresh()->stock);$this->assertSame(1,Purchase::count());$this->assertSame('33.00',Purchase::first()->total);}
 public function test_sale_uses_database_price_and_rejects_insufficient_stock_without_partial_data(): void {[$p]=$this->product(3);$user=$this->user();$this->actingAs($user)->post('/sales',['items'=>[['product_id'=>$p->id,'quantity'=>2,'unit_price'=>'0.01']]])->assertRedirect();$this->assertSame(1,$p->fresh()->stock);$sale=Sale::firstOrFail();$this->assertSame('25.00',$sale->total);$this->actingAs($user)->from('/sales/create')->post('/sales',['items'=>[['product_id'=>$p->id,'quantity'=>5]]])->assertSessionHasErrors('items');$this->assertSame(1,$p->fresh()->stock);$this->assertSame(1,Sale::count());}
 public function test_admin_can_cancel_completed_sale_once_and_staff_cannot(): void {[$p]=$this->product(5);$staff=$this->user();$this->actingAs($staff)->post('/sales',['items'=>[['product_id'=>$p->id,'quantity'=>2]]]);$sale=Sale::firstOrFail();$this->actingAs($staff)->post('/sales/'.$sale->id.'/cancel')->assertForbidden();$admin=$this->user('admin');$this->actingAs($admin)->post('/sales/'.$sale->id.'/cancel')->assertRedirect();$this->assertSame(5,$p->fresh()->stock);$this->actingAs($admin)->post('/sales/'.$sale->id.'/cancel')->assertSessionHasErrors('status');$this->assertSame(5,$p->fresh()->stock);}
 public function test_sale_with_a_bad_second_item_rolls_back_entire_request(): void {[$first]=$this->product(4);[$second]=$this->product(1);$user=$this->user();$this->actingAs($user)->from('/sales/create')->post('/sales',['items'=>[['product_id'=>$first->id,'quantity'=>2],['product_id'=>$second->id,'quantity'=>2]]])->assertSessionHasErrors('items');$this->assertSame(4,$first->fresh()->stock);$this->assertSame(1,$second->fresh()->stock);$this->assertSame(0,Sale::count());}
 public function test_duplicate_sku_is_rejected_by_database_validation(): void {[$p]=$this->product();$admin=$this->user('admin');$this->actingAs($admin)->from('/products/create')->post('/products',['sku'=>$p->sku,'name'=>'Duplicate','category_id'=>$p->category_id,'purchase_price'=>'1.00','selling_price'=>'2.00','minimum_stock'=>0,'stock'=>0])->assertSessionHasErrors('sku');}
 public function test_admin_can_view_management_while_staff_can_list_products(): void {$admin=$this->user('admin');$this->actingAs($admin)->get('/products/create')->assertOk();$this->actingAs($this->user())->get('/products')->assertOk();}
}
